import numpy as np
np.set_printoptions(precision=2, suppress=True, linewidth=200)
W = dict(np.load("weights.npz"))
def sv(M): return np.linalg.svd(M, compute_uv=False)
for l in range(4):
    print(f"===== layer {l}")
    for nm in ["W_q","W_k","W_v"]:
        for j in range(6):
            s = sv(W[f"{nm}.{l}"][64*j:64*j+64,:])
            print(f"{nm} h{j}: ", s[:40])
    for j in range(6):
        s = sv(W[f"W_o.{l}"][:,64*j:64*j+64])
        print(f"W_o h{j}: ", s[:40])
    print("W_fc full:", sv(W[f"W_fc.{l}"])[:60])
    print("W_proj full:", sv(W[f"W_proj.{l}"])[:60])

